# edit_engineimport streamlit as stimport jsonimport sysimport osfrom datetime import datetimefrom pathlib import Path# Add the project root (NoLI_App) to the Python pathroot_path = Path(__file__).resolve().parent.parentif str(root_path) not in sys.path:    sys.path.insert(0, str(root_path))    # Import our specialized toolsfrom engines.edit_tools.ui_components import render_registry_rowfrom engines.edit_tools.file_utilities import get_logic_metadata_dictfrom engines.edit_tools.dropdown_factory import build_edit_dropdown_optionsfrom engines.edit_tools.editor_mechanics import load_logic_content, save_logic_changesfrom utils.config_logic import PROTECTED_FIELDS, TYPE_LABELS# from engines.edit_tools.ui_components import render_registry_row# from engines.edit_tools.file_utilities import get_logic_metadata_dictdef run_edit_workflow(PATHS, get_all_spec_files, extract_itw_display_name):    st.title("Logic Map Files")    st.header("Edit Logic Maps")        spec_files = get_all_spec_files()    if not spec_files:        st.warning("No logic maps found in the /spec directory.")        return    # --- 1. THE TRIGGER (The If) ---    # build_edit_dropdown_options handles the SEM lookup for descriptive names    file_map, display_options = build_edit_dropdown_options(        PATHS, spec_files, extract_itw_display_name    )    selected_label = st.selectbox("Select File", options=[""] + display_options)# --- 2. THE DATA ACTION (The Then) ---    if selected_label:        target_path = file_map[selected_label]        itw_id = extract_itw_display_name(target_path.name)                # 1. Identify the file type prefix (e.g., BRG, SEM, DIC)        prefix = target_path.name.split('_')[0] if '_' in target_path.name else ""                # 2. Get the Friendly Name and Protocol Description from your config        # This unpacks the tuple: ("Bridge", "The kinetic link...")        type_info = TYPE_LABELS.get(prefix, (prefix, "Logic Map File"))        friendly_name, protocol_desc = type_info        # 3. Render the dynamic subtitle and intent        st.subheader(f"{friendly_name}")        st.info(f"**Protocol Intent:** {protocol_desc}")                # Load the content using our mechanics tool        content, sorted_keys = load_logic_content(target_path)                # Grounding: Pull the full 'Why' metadata from the SEM file        logic_context = get_logic_metadata_dict(PATHS, itw_id, prefix="SEM")        # UI Visual: Show the Business Owner if available        if logic_context.get("business_owner"):            st.caption(f"Strategy Lead: {logic_context.get('business_owner')}")        updated_content = {}        st.markdown("---")                # Render the interactive Logic RFC table        for k in sorted_keys:            # Governance check            is_prot = k.lower() in PROTECTED_FIELDS                        # Draw the row and capture changes or deletions            val, delete_clicked = render_registry_row(                k, content[k], is_prot, selected_label            )                        if not delete_clicked:                updated_content[k] = val        # --- 3. THE STRATEGIC INTENT (The Why) ---        st.markdown("---")        if st.button("Save Changes", type="primary"):            # Commit the 'Logic DNA' back to the physical file            if save_logic_changes(target_path, updated_content):                st.success("Logic Synchronized.")                st.rerun()